create type "public"."app_permission" as enum ('awards.read', 'awards.write', 'clubs.read', 'clubs.write', 'club_managers.read', 'club_managers.write', 'claims.read', 'claims.write', 'details.read', 'details.write', 'memberships.read', 'memberships.write', 'users.read', 'users.write');

create type "public"."app_role" as enum ('developer', 'admin', 'cap', 'junior_organizer', 'senior_organizer', 'mc_member', 'user');

create table "public"."awards" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "user_id" bigint not null,
    "award" text not null,
    "level" smallint not null
);


create table "public"."claims" (
    "id" bigint generated by default as identity not null,
    "user_id" bigint not null,
    "role" app_role not null default 'user'::app_role,
    "credential" smallint not null default 0
);


create table "public"."club_managers" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "club_id" bigint not null,
    "user_id" bigint not null
);


create table "public"."clubs" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "name" text not null,
    "active" boolean not null default true,
    "league" text not null default 'senior'::text
);


create table "public"."details" (
    "id" bigint generated by default as identity not null,
    "user_id" bigint not null,
    "birthdate" date,
    "address" text,
    "email" text,
    "phone" text
);


create table "public"."memberships" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "user_id" bigint not null,
    "club_id" bigint not null,
    "year" smallint not null
);


create table "public"."role_permissions" (
    "id" bigint generated by default as identity not null,
    "role" app_role not null,
    "permission" app_permission not null
);


create table "public"."users" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "auth_id" uuid default auth.uid(),
    "name" text,
    "surname" text,
    "public" boolean not null default false
);


CREATE UNIQUE INDEX awards_pkey ON public.awards USING btree (id);

CREATE UNIQUE INDEX awards_user_id_award_level_key ON public.awards USING btree (user_id, award, level);

