CREATE UNIQUE INDEX club_managers_club_id_user_id_key ON public.club_managers USING btree (club_id, user_id);

CREATE UNIQUE INDEX club_managers_pkey ON public.club_managers USING btree (id);

CREATE UNIQUE INDEX clubs_pkey ON public.clubs USING btree (id);

CREATE UNIQUE INDEX details_pkey ON public.details USING btree (id);

CREATE UNIQUE INDEX details_user_id_key ON public.details USING btree (user_id);

CREATE UNIQUE INDEX memberships_pkey ON public.memberships USING btree (id);

CREATE UNIQUE INDEX memberships_user_id_club_id_year_key ON public.memberships USING btree (user_id, club_id, year);

CREATE UNIQUE INDEX role_permissions_pkey ON public.role_permissions USING btree (id);

CREATE UNIQUE INDEX role_permissions_role_permission_key ON public.role_permissions USING btree (role, permission);

CREATE UNIQUE INDEX users_auth_id_key ON public.users USING btree (auth_id);

CREATE UNIQUE INDEX users_pkey ON public.users USING btree (id);

