CREATE OR REPLACE FUNCTION public.authorize(requested_permission app_permission)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bind_permissions int;
  current_user_role public.app_role;
begin
  -- Retrieves the 'user_role' claim from the current user's JWT.
  -- This will be NULL if the claim is not set or is JSON null.
  select (auth.jwt() ->> 'user_role')::public.app_role into current_user_role;

  -- If current_user_role is NULL (e.g., claim missing, or was explicitly set to null),
  -- then the user has no specific role for permission checking.
  if current_user_role is null then
    return false;
  end if;

  -- Checks if the user's role has the requested permission in the 'role_permissions' table.
  select count(*)
  into bind_permissions
  from public.role_permissions
  where role_permissions.permission = requested_permission
    and role_permissions.role = current_user_role;
  return bind_permissions > 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
  declare
    claims_from_event jsonb;
    user_role public.app_role;
  begin
    -- Fetches the user's application role from the 'claims' table.
    select c.role
    into user_role
    from public.claims as c
    join public.users as u on c.user_id = u.id
    where u.auth_id = (event->>'user_id')::uuid;

    claims_from_event := event->'claims';

    if user_role is not null then
      -- Sets the 'user_role' claim in the JWT.
      claims_from_event := jsonb_set(claims_from_event, '{user_role}', to_jsonb(user_role));
    else
      -- Sets the 'user_role' claim to JSON null if the user_role is not found.
      claims_from_event := jsonb_set(claims_from_event, '{user_role}', to_jsonb(null::public.app_role));
    end if;

    -- Updates the 'claims' object within the original event JSON.
    event := jsonb_set(event, '{claims}', claims_from_event);

    -- Returns the modified event with the new claim.
    return event;
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.claims (user_id, role, credential)
  values (new.id, 'user', 0);
  insert into public.details (user_id)
  values (new.id);
  return new;
end;
$function$
;

