create policy "Allow authenticated users to read public user awards"
on "public"."awards"
as permissive
for select
to authenticated
using ((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = awards.user_id) AND (users.public = true)))));


create policy "Allow user roles to create awards"
on "public"."awards"
as permissive
for insert
to authenticated
with check (authorize('awards.write'::app_permission));


create policy "Allow user roles to delete awards"
on "public"."awards"
as permissive
for delete
to authenticated
using (authorize('awards.write'::app_permission));


create policy "Allow user roles to read awards"
on "public"."awards"
as permissive
for select
to authenticated
using (authorize('awards.read'::app_permission));


create policy "Allow user roles to update awards"
on "public"."awards"
as permissive
for update
to authenticated
using (authorize('awards.write'::app_permission));


create policy "Allow users to read their own awards"
on "public"."awards"
as permissive
for select
to authenticated
using ((auth.uid() = ( SELECT users.auth_id
   FROM users
  WHERE (users.id = awards.user_id))));


create policy "Allow anyone to read user claims"
on "public"."claims"
as permissive
for select
to public
using (true);


create policy "Allow user roles to update user claims"
on "public"."claims"
as permissive
for update
to authenticated
using (authorize('claims.write'::app_permission))
with check (authorize('claims.write'::app_permission));


create policy "Allow authenticated users to read club managers for active club"
on "public"."club_managers"
as permissive
for select
to authenticated
using (((EXISTS ( SELECT 1
   FROM clubs
  WHERE ((clubs.id = club_managers.club_id) AND (clubs.active = true)))) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = club_managers.user_id) AND (users.public = true))))));


