using (authorize('users.write'::app_permission));


create policy "Allow users to create their own data"
on "public"."users"
as permissive
for insert
to authenticated
with check ((auth.uid() = auth_id));


create policy "Allow users to read their own data"
on "public"."users"
as permissive
for select
to authenticated
using ((auth.uid() = auth_id));


create policy "Allow users to update their own data"
on "public"."users"
as permissive
for update
to authenticated
using ((auth.uid() = auth_id))
with check ((auth.uid() = auth_id));


CREATE TRIGGER on_user_created AFTER INSERT ON public.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();


